CREATE OR REPLACE FUNCTION public.icash_admit_owner_active_export(p_account uuid, p_primary uuid, p_batch uuid, p_items jsonb, p_preview jsonb, p_config jsonb, p_request jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ids jsonb;expected jsonb;admission text;item jsonb;person text;preview jsonb;match jsonb;
begin
 if not public.icash_owner_active_export_enabled() then return 'held';end if;
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 5 then return 'held';end if;
 select jsonb_agg(to_jsonb(id) order by position) into ids from (
  select v#>>'{}' as id,min(i.ordinality*1000+p.ordinality) as position
  from jsonb_array_elements(p_items) with ordinality i(item,ordinality),jsonb_array_elements(i.item->'ids') with ordinality p(v,ordinality) group by v
 ) u;
 if jsonb_array_length(ids) not between 1 and 125 or exists(select 1 from jsonb_array_elements_text(ids) id where id !~ '^per_[0-9]{1,100}$') then return 'held';end if;
 expected:=jsonb_build_object('people_ids',ids,'fields','["person_full_name","has_active_phone_number"]'::jsonb,'property_match','owner','anchor','person','limit',jsonb_array_length(ids),'require_phone',true,'scrub_dnc',true,'active_phones_only',true);
 if p_request is distinct from expected then return 'held';end if;
 -- SQL repeats owner/phone availability proof before any quota or wallet claim.
 for item in select value from jsonb_array_elements(p_items) loop
  select value into strict preview from jsonb_array_elements(p_preview->'data') where value->>'dm_property_id'=item->'snapshot'->>'propertyId' and value->'found'='true'::jsonb;
  if (select count(distinct value) from jsonb_array_elements(item->'ids'))<>jsonb_array_length(item->'ids') then return 'held';end if;
  for person in select value from jsonb_array_elements_text(item->'ids') loop
   select value into match from jsonb_array_elements(preview->'contacts') where value->>'dm_person_id'=person limit 1;
   if not found or (match->>'contact_type' is not null and match->>'contact_type'<>'owner')
    or match->'is_likely_renter'='true'::jsonb
    or (match->'is_likely_owner'='true'::jsonb or (match->>'is_likely_owner' is null and match->>'contact_type'='owner')) is distinct from true
    or match->'availability'->'phones'='0'::jsonb then return 'held';end if;
  end loop;
 end loop;
 if not pg_try_advisory_xact_lock(hashtextextended('dealmachine:organization:owner-export',0)) then return 'export_busy';end if;
 if exists(select 1 from icash_research_private.owner_exports where terminal_at is null and capacity_review_id is null) then return 'export_busy';end if;
 admission:=public.icash_admit_owner_batch(p_account,p_primary,p_batch,p_items,p_preview,p_config||'{"ownerContract":"owner-active-export-v1"}');
 if admission<>'claimed' then return admission;end if;
 insert into icash_research_private.owner_exports(id,request) values(p_batch,p_request);
 return 'claimed';
end $function$

CREATE OR REPLACE FUNCTION public.icash_discovery_filter_state_v2(p_account uuid, p_revision uuid, p_page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare source jsonb;c public.icash_discovery_configs;
begin
 source:=public.icash_filter_state_before_request_reuse(p_account,p_revision,p_page);
 if source is null then return null;end if;
 select * into c from public.icash_discovery_configs where account_id=p_account;
 return (select jsonb_agg(item||jsonb_build_object('blocked',exists(
  select 1 from public.icash_discovery_filter_pages fp
  join public.icash_operation_spend os using(operation_key,account_id)
  join public.icash_discovery_configs dc on dc.account_id=fp.account_id
  where fp.zip=c.zip and fp.plan->>'strategy'=item->>'strategy'
   and fp.plan->>'providerPage'=item->>'nextPage' and dc.per_page=c.per_page
   and fp.state='claimed' and os.state not in ('settled','cancelled')
 ))) from jsonb_array_elements(source) item);
end $function$

CREATE OR REPLACE FUNCTION public.icash_finish_empty_filter(p_account uuid, p_revision uuid, p_page integer, p_plan jsonb, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;op text:='discovery:'||p_account||':'||p_revision||':'||p_page;
begin
 if not public.icash_discovery_filter_plan_valid(p_plan) or p_reason not in ('empty','unavailable') or p_reason is null
 or (p_reason='unavailable' and p_plan->>'strategy'='baseline') then return false;end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found or c.revision<>p_revision or c.next_page<>p_page
 or exists(select 1 from public.icash_operation_spend where operation_key=op)
 or exists(select 1 from public.icash_discovery_filter_pages where operation_key=op) then return false;end if;
 perform 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and zip=c.zip
 and strategy=p_plan->>'strategy' and next_page=(p_plan->>'providerPage')::integer and not exhausted for update;
 if not found then return false;end if;
 insert into public.icash_discovery_filter_pages(operation_key,account_id,revision,sequence,zip,plan,state,completed_at) values(op,p_account,p_revision,p_page,c.zip,p_plan,p_reason,now());
 update public.icash_discovery_filter_cursors set exhausted=true,pages=pages+1 where account_id=p_account and revision=p_revision and strategy=p_plan->>'strategy';
 if not exists(select 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted) then
  perform public.icash_mark_inventory_empty(p_account,p_revision,p_page);
 else update public.icash_discovery_configs set next_page=next_page+1 where account_id=p_account and revision=p_revision;
 end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_prepare_discovery_inventory(p_account uuid, p_revision uuid, p_page integer)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;cur record;cached jsonb;n integer:=0;streak integer;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found or c.revision<>p_revision or c.next_page<>p_page or not c.enabled or not c.auto_enabled or c.data_rights_until<=now()
 or not exists(select 1 from public.icash_accounts a join public.icash_wallets w on w.account_id=a.id where a.id=p_account and not a.bot_paused and w.balance_cents>w.reserved_cents)
 or not public.icash_membership_work_allowed(p_account) then return 'inventory_held';end if;
 if exists(select 1 from public.icash_operation_spend where operation_key='discovery:'||p_account||':'||p_revision||':'||p_page and state<>'reserved') then return 'awaiting_reconciliation';end if;
 perform public.icash_expand_inventory_markets(p_account);
 select count(*) into streak from (select queued_properties,returned_properties,duplicate_properties from public.icash_discovery_inventory_receipts where account_id=p_account and revision=p_revision order by created_at desc limit 3) recent
 where queued_properties=0 and returned_properties=duplicate_properties;
 if streak=3 then
  update public.icash_inventory_markets set next_scan_at=greatest(next_scan_at,now()+interval '6 hours') where account_id=p_account and zip=c.zip;
  update public.icash_discovery_configs set exhausted=true where account_id=p_account;
  if public.icash_rotate_inventory_market(p_account) then return 'inventory_market_changed';end if;
  return 'inventory_waiting';
 end if;
 if not exists(select 1 from public.icash_discovery_filter_settings where id=1 and enabled) then return 'ready';end if;
 perform public.icash_discovery_filter_state_v2(p_account,p_revision,p_page);
 if c.research_list_id is not null then return 'ready';end if;
 for cur in select * from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted order by strategy for update loop
  loop
   cached:=public.icash_known_assigned_research_page(c.zip,cur.strategy,cur.next_page,c.per_page,
  case when c.research_version in (1,2) then jsonb_build_object('version',case when c.research_version=2 then 'research-efficiency-v2' else 'research-efficiency-v1' end,'exclusionListId',null) end);
   exit when cached is null;
   update public.icash_discovery_filter_cursors set next_page=next_page+1,skipped_assigned_pages=skipped_assigned_pages+1,exhausted=not (cached->>'hasNextPage')::boolean
   where account_id=p_account and revision=p_revision and strategy=cur.strategy;
   cur.next_page:=cur.next_page+1;n:=n+1;
   if n>=64 then return 'inventory_advancing';end if;
   exit when not (cached->>'hasNextPage')::boolean;
  end loop;
 end loop;
 if not exists(select 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted) then
  perform public.icash_mark_inventory_empty(p_account,p_revision,p_page);
  if exists(select 1 from public.icash_discovery_configs where account_id=p_account and revision<>p_revision) then return 'inventory_market_changed';end if;
  return 'inventory_waiting';
 end if;
 return 'ready';
end $function$

CREATE OR REPLACE FUNCTION public.icash_prepare_research_efficiency(p_account uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;r public.icash_operation_rates;base uuid;chosen uuid;large uuid;size integer:=5;list text;cap bigint;quote bigint;
begin
 if not exists(select 1 from icash_research_private.settings where id=1 and enabled) then return false;end if;
 perform public.icash_continue_stalled_research(p_account);
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;
 if not found or not public.icash_membership_work_allowed(p_account) then return false;end if;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found or not c.enabled or not c.auto_enabled or c.data_rights_until<=now() then return false;end if;
 -- Never rotate away from an unknown or reserved purchase, including old revisions.
 if exists(select 1 from public.icash_operation_spend where account_id=p_account and operation_key like 'discovery:%' and state in ('reserved','dispatched')
  and not exists(select 1 from icash_research_private.stalled_searches q where q.operation_key=public.icash_operation_spend.operation_key and q.account_id=p_account and q.zip<>c.zip)) then return false;end if;
 select base_rate into base from icash_research_private.account_rates where account_id=p_account;
 if base is null then base:=c.rate_id;insert into icash_research_private.account_rates values(p_account,base);end if;
 select * into r from public.icash_operation_rates where id=base;
 if not found or not r.enabled or r.expires_at<=now() or r.operation<>'property_search' then return false;end if;
 -- A deliberate external rate change becomes the new baseline; never restore a stale rate.
 if c.rate_id<>base and not exists(select 1 from icash_research_private.rate_versions where base_rate=base and batch_rate=c.rate_id) then
  update icash_research_private.account_rates set base_rate=c.rate_id where account_id=p_account;return false;
 end if;
 select batch_rate into large from icash_research_private.rate_versions where base_rate=base and unit_micros=c.property_credit_micros;
 if large is null then
  large:=gen_random_uuid();
  cap:=greatest((r.costs_micros->>'dealmachine')::bigint,c.property_credit_micros*25);
  quote:=r.charge_cents+ceil((cap-(r.costs_micros->>'dealmachine')::bigint)::numeric*3*(10000+r.buffer_bps)/100000000)::bigint;
  insert into public.icash_operation_rates(id,operation,version,charge_cents,costs_micros,buffer_bps,evidence_ref,verified_at,expires_at,enabled,voice_max_duration_seconds,flat_customer_price_cents)
  values(large,r.operation,'research25-'||large,quote,jsonb_set(r.costs_micros,'{dealmachine}',to_jsonb(cap)),r.buffer_bps,'research-efficiency-v1:base:'||base,r.verified_at,r.expires_at,r.enabled,r.voice_max_duration_seconds,r.flat_customer_price_cents);
  insert into icash_research_private.rate_versions values(base,c.property_credit_micros,large);
 end if;
 chosen:=base;
 select charge_cents into quote from public.icash_operation_rates where id=large and enabled and expires_at>now();
 if quote is not null and c.max_open_prospects>=20
  and public.icash_prospecting_available(p_account)>=public.icash_research_admission_quote(p_account,'property_search',quote)
  and exists(select 1 from public.icash_wallets where account_id=p_account and balance_cents-reserved_cents>=public.icash_research_admission_quote(p_account,'property_search',quote)) then chosen:=large;size:=25;end if;
 select list_id into list from icash_research_private.exclusions where id=1 and state='ready'
  and not exists(select 1 from icash_research_private.exclusion_items where synced_at is null);
 -- An active exclusion list stays attached while its next free sync is pending.
 list:=case when (select exclusions_enabled from icash_research_private.settings where id=1) then coalesce(list,c.research_list_id) else null end;
 if row(c.research_version,c.rate_id,c.per_page,c.research_list_id) is distinct from row(2,chosen,size,list) then
  update public.icash_discovery_configs set research_version=2,rate_id=chosen,per_page=size,research_list_id=list,
   max_open_prospects=case when max_open_prospects=20 then 25 else max_open_prospects end,revision=gen_random_uuid(),next_page=1,exhausted=false where account_id=p_account;
 end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_record_discovery_inventory()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;ids text[];queued integer;duplicates integer;plan jsonb;
begin
 select (jsonb_populate_record(null::public.icash_discovery_configs,public.icash_stalled_search_configuration(new.account_id,new.operation_key))).* into c;
 if c.account_id is null then select * into strict c from public.icash_discovery_configs where account_id=new.account_id; end if;
 select coalesce(array_agg(value->>'dm_property_id'),'{}') into ids from jsonb_array_elements(new.result->'rows');
 select count(*) into queued from public.icash_screening_jobs s where s.account_id=new.account_id
 and s.event_key in (select new.operation_key||':'||pid.property_id from unnest(ids) as pid(property_id));
 select count(*) into duplicates from unnest(ids) as pid(property_id)
 join public.icash_outbound_property_owners o on o.property_id=pid.property_id
 where not exists(select 1 from public.icash_screening_jobs s where s.account_id=new.account_id
  and s.event_key=new.operation_key||':'||pid.property_id);
 plan:=new.result->'filterPlan';
 insert into public.icash_discovery_inventory_receipts(operation_key,account_id,revision,zip,strategy,provider_page,per_page,property_ids,returned_properties,queued_properties,duplicate_properties,has_next_page,created_at,query_policy)
 values(new.operation_key,new.account_id,c.revision,c.zip,coalesce(plan->>'strategy','baseline'),case when new.result->'queryPolicy'->>'exclusionListId' is not null then 1 else coalesce((plan->>'providerPage')::integer,c.next_page) end,c.per_page,ids,cardinality(ids),queued,duplicates,(new.result->>'hasNextPage')::boolean,new.created_at,new.result->'queryPolicy');
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_and_claim_filtered_discovery(p_account uuid, p_zip text, p_revision uuid, p_page integer, p_per_page integer, p_rate uuid, p_unit bigint, p_permission_until timestamp with time zone, p_setup_revision integer, p_market_mode text, p_market text, p_plan jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare op text:='discovery:'||p_account||':'||p_revision||':'||p_page;
begin
 if not public.icash_discovery_filter_plan_valid(p_plan) then return false;end if;
 -- The original admission function retains every budget, permission and scope gate.
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 perform 1 from public.icash_discovery_configs where account_id=p_account for update;
 if not exists(select 1 from public.icash_discovery_filter_settings where id=1 and enabled)
 or exists(select 1 from public.icash_discovery_filter_pages where operation_key=op) then return false;end if;
 perform 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and zip=p_zip
 and strategy=p_plan->>'strategy' and next_page=(p_plan->>'providerPage')::integer and not exhausted for update;
 if not found then return false;end if;
 if ((select research_version=0 from public.icash_discovery_configs where account_id=p_account) and public.icash_known_assigned_discovery_page(p_zip,p_plan->>'strategy',(p_plan->>'providerPage')::integer,p_per_page) is not null)
 or exists(select 1 from public.icash_discovery_filter_pages fp join public.icash_operation_spend os using(operation_key,account_id)
 join public.icash_discovery_configs dc on dc.account_id=fp.account_id where fp.zip=p_zip and fp.plan->>'strategy'=p_plan->>'strategy'
 and fp.plan->>'providerPage'=p_plan->>'providerPage' and dc.per_page=p_per_page and fp.state='claimed' and os.state not in ('settled','cancelled')) then return false;end if;
 if not public.icash_reserve_and_claim_property_discovery(p_account,p_zip,p_revision,p_page,p_per_page,p_rate,p_unit,p_permission_until,p_setup_revision,p_market_mode,p_market) then return false;end if;
 insert into public.icash_discovery_filter_pages(operation_key,account_id,revision,sequence,zip,plan,state) values(op,p_account,p_revision,p_page,p_zip,p_plan,'claimed');
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_research_discovery(p_account uuid, p_scope jsonb, p_plan jsonb, p_policy jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;ok boolean;op text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if coalesce(c.research_version,0) not in (1,2) or p_policy is distinct from jsonb_build_object('version',case when c.research_version=2 then 'research-efficiency-v2' else 'research-efficiency-v1' end,'exclusionListId',c.research_list_id) then return false;end if;
 if c.research_list_id is not null and exists(select 1 from icash_research_private.exclusion_items where synced_at is null) then return false;end if;
 if not public.icash_research_query_ready(p_account,p_scope,p_plan,p_policy) then return false;end if;
 if p_plan is not null then
  ok:=public.icash_reserve_and_claim_filtered_discovery(p_account,p_scope->>'p_zip',(p_scope->>'p_revision')::uuid,(p_scope->>'p_page')::integer,(p_scope->>'p_per_page')::integer,(p_scope->>'p_rate')::uuid,(p_scope->>'p_unit')::bigint,(p_scope->>'p_permission_until')::timestamptz,(p_scope->>'p_setup_revision')::integer,p_scope->>'p_market_mode',p_scope->>'p_market',p_plan);
 else
  ok:=public.icash_reserve_and_claim_property_discovery(p_account,p_scope->>'p_zip',(p_scope->>'p_revision')::uuid,(p_scope->>'p_page')::integer,(p_scope->>'p_per_page')::integer,(p_scope->>'p_rate')::uuid,(p_scope->>'p_unit')::bigint,(p_scope->>'p_permission_until')::timestamptz,(p_scope->>'p_setup_revision')::integer,p_scope->>'p_market_mode',p_scope->>'p_market');
 end if;
 if not ok then return false;end if;
 op:='discovery:'||p_account||':'||(p_scope->>'p_revision')||':'||(p_scope->>'p_page');
 insert into icash_research_private.query_claims values(op,p_account,p_policy);return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_save_filtered_discovery(p_account uuid, p_operation text, p_revision uuid, p_page integer, p_result jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare page public.icash_discovery_filter_pages;n integer;saved jsonb;
begin
 perform 1 from public.icash_operation_spend where operation_key=p_operation and account_id=p_account for update;
 if not found then raise exception 'Filter operation required';end if;
 select * into page from public.icash_discovery_filter_pages where operation_key=p_operation and account_id=p_account for update;
 if not found or page.revision<>p_revision or page.sequence<>p_page or page.plan is distinct from p_result->'filterPlan' then raise exception 'Filter receipt scope changed';end if;
 if page.state='complete' then
  select result into saved from public.icash_discovery_results where operation_key=p_operation and account_id=p_account;
  if saved is distinct from p_result then raise exception 'Filter result conflict';end if;
  return (select count(*)::integer from public.icash_discovery_filter_attribution where operation_key=p_operation and account_id=p_account);
 end if;
 if page.state<>'claimed' then raise exception 'Filter claim required';end if;
 n:=public.icash_save_discovery(p_account,p_operation,p_revision,p_page,p_result);
 insert into public.icash_discovery_filter_attribution(screening_id,account_id,operation_key)
 select s.id,s.account_id,p_operation from public.icash_screening_jobs s
 where s.account_id=p_account and s.event_key=p_operation||':'||(s.snapshot->>'propertyId') on conflict do nothing;
 update public.icash_discovery_filter_cursors set next_page=case when p_result->'queryPolicy'->>'exclusionListId' is not null then 1 else next_page+1 end,pages=pages+1,exhausted=not coalesce((p_result->>'hasNextPage')::boolean,false)
 where account_id=p_account and revision=p_revision and strategy=page.plan->>'strategy';
 update public.icash_discovery_filter_pages set state='complete',completed_at=now() where operation_key=p_operation;
 update public.icash_discovery_configs set exhausted=not exists(select 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted)
 where account_id=p_account and revision=p_revision;
 return n;
end $function$

CREATE OR REPLACE FUNCTION public.icash_save_owner_active_export(p_batch uuid, p_lease uuid, p_results jsonb, p_rows jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e icash_research_private.owner_exports;b icash_research_private.owner_batches;receipt jsonb;credits jsonb;item jsonb;r jsonb;person text;row_data jsonb;match jsonb;contacts jsonb;phones jsonb;expected jsonb;assigned text[]:='{}';unique_count integer;remaining integer;used integer;i integer;op text;key text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into e from icash_research_private.owner_exports where id=p_batch for update;
 select * into b from icash_research_private.owner_batches where id=p_batch for update;
 if e.completed_at is not null then return b.results=p_results and e.parsed_rows=p_rows;end if;
 if e.id is null or e.lease_token is distinct from p_lease or e.lease_until<=clock_timestamp() or e.csv is null or e.receipt->'httpStatus' is distinct from '200'::jsonb then return false;end if;
 receipt:=e.receipt->'raw';credits:=receipt->'credits';
 if jsonb_typeof(credits) is distinct from 'object' or jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows)>125 or octet_length(p_rows::text)>1048576
  or jsonb_typeof(p_results) is distinct from 'array' or jsonb_array_length(p_results)<>jsonb_array_length(b.items)
  or receipt->'record_count' is distinct from to_jsonb(jsonb_array_length(p_rows)) or receipt->'file_count' is distinct from '1'::jsonb
  or jsonb_typeof(credits->'people') is distinct from 'number' or coalesce(credits->>'people','') !~ '^[0-9]{1,3}$'
  or (credits->>'people')::integer<jsonb_array_length(p_rows) or (credits->>'people')::integer>jsonb_array_length(e.request->'people_ids')
  or e.recovery->'raw'->'data'->'record_count' is distinct from receipt->'record_count'
  or coalesce(credits->>'used','') !~ '^[0-9]{1,3}$' or jsonb_typeof(credits->'used') is distinct from 'number'
  or (credits->>'used')::integer>jsonb_array_length(p_rows)
  or (credits ? 'properties' and credits->'properties' is distinct from '0'::jsonb) then raise exception 'Export credit contract mismatch';end if;
 for key in select jsonb_object_keys(credits) loop
  if key not in ('used','people','properties','deduplicated','licensed') or jsonb_typeof(credits->key) is distinct from 'number' or coalesce(credits->>key,'') !~ '^[0-9]{1,3}$' then raise exception 'Unverified export credit field';end if;
 end loop;
 if (select count(distinct value->>'internal_person_id') from jsonb_array_elements(p_rows))<>jsonb_array_length(p_rows)
  or exists(select 1 from jsonb_array_elements(p_rows) x where not(e.request->'people_ids' ? ('per_'||(x->>'internal_person_id'))) or coalesce(x->>'has_active_phone_number','') not in ('Yes','true')) then raise exception 'Export owner mapping mismatch';end if;
 remaining:=(credits->>'used')::integer;
 for item in select value from jsonb_array_elements(b.items) loop
  contacts:='[]';unique_count:=0;
  for person in select value from jsonb_array_elements_text(item->'ids') loop
   select value into row_data from jsonb_array_elements(p_rows) where 'per_'||(value->>'internal_person_id')=person;
   if not found then continue;end if;
   if not(person=any(assigned)) then assigned:=array_append(assigned,person);unique_count:=unique_count+1;end if;
   select p into strict match from jsonb_array_elements(b.preview_receipt->'data') property,jsonb_array_elements(property->'contacts') p where property->>'dm_property_id'=item->'snapshot'->>'propertyId' and p->>'dm_person_id'=person limit 1;
   phones:='[]';
   for i in 1..3 loop
    if coalesce(row_data->>('phone_'||i),'')='' then continue;end if;
    if coalesce(row_data->>('is_phone_'||i||'_dnc'),'') not in ('No','false') then raise exception 'Export DNC evidence mismatch';end if;
    phones:=phones||jsonb_build_array(jsonb_build_object('number',row_data->>('phone_'||i),'doNotCall',false,'type',row_data->>('people_phone_'||i||'_type_id'),'permission','unverified','activity','active','activityBasis','provider_export_filter'));
   end loop;
   contacts:=contacts||jsonb_build_array(jsonb_build_object('personId',person,'name',row_data->>'person_full_name','likelyOwner',true,'propertyContactType',case when match->>'contact_type'='owner' then 'owner' else null end,
    'matchFlags',jsonb_build_object('is_likely_owner',match->'is_likely_owner','is_in_owner_family',match->'is_in_owner_family','is_resident',match->'is_resident','is_likely_renter',match->'is_likely_renter'),
    'ownershipVerified',false,'outreachAuthorized',false,'phones',phones,'emails','[]'::jsonb));
  end loop;
  used:=least(remaining,unique_count);remaining:=remaining-used;
  select value->'result' into strict r from jsonb_array_elements(p_results) where value->>'screeningId'=item->>'screeningId';
  expected:=jsonb_build_object('propertyId',item->'snapshot'->>'propertyId','creditsUsed',used,'peopleCredits',unique_count,'providerCredits',credits,'requestedPersonIds',item->'ids','contacts',contacts,'outreachAuthorized',false,
   'fetchedAt',to_char(b.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
   'allocation',jsonb_build_object('batchId',p_batch,'method','active-export-used-order-v1','sharedContacts',jsonb_array_length(contacts)-unique_count),
   'activityEvidence',jsonb_build_object('contract','owner-active-export-v1','exportId',receipt->>'export_id','artifactSha256',e.artifact_sha256));
  if r is distinct from expected or not public.icash_owner_export_result_valid(r) then raise exception 'Export allocation or source mismatch';end if;
  op:='owners:'||b.account_id||':'||(item->>'screeningId');
  perform public.icash_save_contacts(b.account_id,(item->>'screeningId')::uuid,op,r);
 end loop;
 if remaining<>0 or cardinality(assigned)<>jsonb_array_length(p_rows) then raise exception 'Export allocation incomplete';end if;
 update icash_research_private.owner_batches set state='complete',results=p_results where id=p_batch;
 update icash_research_private.owner_exports set parsed_rows=p_rows,completed_at=clock_timestamp() where id=p_batch;
 for op in select operation_key from icash_research_private.owner_batch_items where batch_id=p_batch order by operation_key loop
  if not public.icash_settle_dealmachine_usage(op) then raise exception 'Export actual usage settlement held';end if;
 end loop;
 return true;
end $function$
